public without sharing class LogPurgeJob implements Schedulable {
    private static final String JOB_NAME = 'Log purge (nightly)';
    private static final String CRON_EXP = '0 0 2 * * ?';
    private static final Integer RETENTION_DAYS = 30;
    private static final Integer ERROR_RETENTION_DAYS = 180;
    private static final String LEVEL_ERROR = 'ERROR';

    public LogPurgeJob() {
    }

    public static Id scheduleNightly() {
        return System.schedule(JOB_NAME, CRON_EXP, new LogPurgeJob());
    }

    public void execute(SchedulableContext sc) {
        Datetime retentionCutoff = Datetime.now().addDays(-RETENTION_DAYS);
        Datetime errorRetentionCutoff = Datetime.now().addDays(-ERROR_RETENTION_DAYS);

        List<FB_Integration_Log__c> logsToDelete = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE CreatedDate < :errorRetentionCutoff
                OR (
                    CreatedDate < :retentionCutoff
                    AND (Level__c = null OR Level__c != :LEVEL_ERROR)
                )
        ];

        if (!logsToDelete.isEmpty()) {
            delete logsToDelete;
        }
    }
}
