```apex
/**
 * Asynchronous CSAT survey step for newly closed Case(s).
 *
 * The one-Id constructor matches the required per-Case enqueue. A list
 * constructor is also provided so the trigger can stay within the 50
 * System.enqueueJob-per-transaction limit when agents or the nightly cleanup
 * close up to 200 Cases: overflow Cases are packed into the already-enqueued
 * jobs instead of being chained. Chaining Queueables is what caused
 * System.AsyncException: Maximum stack depth has been reached under
 * nightlyCleanupOf200 (Apex tests do not allow Queueable chaining).
 *
 * execute() is bulk-safe and isolates per-Case DML failures so one bad
 * Task cannot block the others in the same job. Database.AllowsCallouts is
 * declared now so the planned vendor integration can be added without
 * changing the job's contract.
 */
public without sharing class CaseSurveyJob implements Queueable, Database.AllowsCallouts {
    private final List<Id> caseIds;

    public CaseSurveyJob(Id caseId) {
        this.caseIds = new List<Id>();
        if (caseId != null) {
            this.caseIds.add(caseId);
        }
    }

    public CaseSurveyJob(List<Id> caseIds) {
        this.caseIds = caseIds == null ? new List<Id>() : new List<Id>(caseIds);
    }

    public void execute(QueueableContext context) {
        if (caseIds.isEmpty()) {
            return;
        }

        List<Case> closedCases = [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id IN :caseIds AND ContactId != null
        ];

        if (closedCases.isEmpty()) {
            return;
        }

        List<Task> surveyTasks = new List<Task>();
        for (Case closedCase : closedCases) {
            surveyTasks.add(
                new Task(
                    WhatId = closedCase.Id,
                    WhoId = closedCase.ContactId,
                    Subject = 'CSAT survey: ' + closedCase.CaseNumber,
                    ActivityDate = Date.today().addDays(2),
                    Status = 'Not Started'
                )
            );
        }

        // Partial success: one failed Task must not roll back the rest.
        Database.insert(surveyTasks, false);
    }
}
